class Stack<T> implements AutoCloseable {
    private final Deque<T> items = new ArrayDeque<>();
    void push(T item) { items.push(item); }
    T pop() {
        if (items.isEmpty()) throw new NoSuchElementException("stack is empty");
        return items.pop();
    }
    public void close() { System.out.println("stack closed, " + items.size() + " left"); }
}

