import random

def checksum(payload):
    total = 0
    for byte in payload.encode():
        total = (total + byte) & 0xFFFF
    return (~total) & 0xFFFF

def send(payload, corrupt):
    wire = payload.replace("o", "0") if corrupt else payload
    return wire, checksum(payload)

