import hashlib, json, time

class Block:
    def __init__(self, index, data, previous):
        self.index, self.data, self.previous, self.nonce = index, data, previous, 0
        self.timestamp = 1_700_000_000 + index
    def hash(self):
        blob = json.dumps({
            "i": self.index, "d": self.data, "p": self.previous,
            "n": self.nonce, "t": self.timestamp}, sort_keys=True)
        return hashlib.sha256(blob.encode()).hexdigest()
    def mine(self, difficulty):
        while not self.hash().startswith("0" * difficulty):
            self.nonce += 1
        return self.hash()

chain = [Block(0, "genesis", "0" * 64)]
chain[0].mine(3)

for i, payload in enumerate(["Asha -> Rahul : 5", "Rahul -> Meera : 2"], start=1):
