import re

TOKEN = re.compile(r"\s*(?:(\d+\.?\d*)|(.))")

def tokenize(text):
    out = []
    for number, symbol in TOKEN.findall(text):
        out.append(("num", float(number)) if number else ("op", symbol))
    return out + [("end", None)]

class Parser:
    def __init__(self, tokens): self.t, self.i = tokens, 0
    def peek(self): return self.t[self.i]
    def eat(self): self.i += 1; return self.t[self.i - 1]

    def expr(self):
        value = self.term()
        while self.peek()[1] in ("+", "-"):
            op = self.eat()[1]
            value = value + self.term() if op == "+" else value - self.term()
        return value

    def term(self):
        value = self.factor()
        while self.peek()[1] in ("*", "/"):
            op = self.eat()[1]
            value = value * self.factor() if op == "*" else value / self.factor()
        return value

    def factor(self):
        kind, value = self.eat()
        if kind == "num": return value
        if value == "(":
            inner = self.expr()
            self.eat()
            return inner
        if value == "-": return -self.factor()
        raise SyntaxError(f"unexpected {value}")

for src in ["2 + 3 * 4", "(2 + 3) * 4", "10 / 4 - 1", "-3 + 2 * (1 + 1)"]:
    print(f"{src:20} = {Parser(tokenize(src)).expr()}")

