import math

cube = [(x, y, z) for x in (-1, 1) for y in (-1, 1) for z in (-1, 1)]

def rotate_y(p, angle):
    x, y, z = p
    c, s = math.cos(angle), math.sin(angle)
    return (x * c + z * s, y, -x * s + z * c)

def project(p, distance=4.0):
    x, y, z = p
    factor = distance / (distance - z)
    return (x * factor, y * factor)

W, H = 44, 20
for angle in (0.0, math.pi / 4):
    grid = [[" "] * W for _ in range(H)]
    for corner in cube:
        px, py = project(rotate_y(corner, angle))
        cx = int((px + 2) / 4 * (W - 1))
        cy = int((2 - py) / 4 * (H - 1))
        if 0 <= cx < W and 0 <= cy < H:
            grid[cy][cx] = "#"
    print(f"cube rotated {math.degrees(angle):.0f} degrees")
    for row in grid:
        line = "".join(row).rstrip()
        if line:
            print("  " + line)
    print()

import math, re
from collections import Counter

docs = {
    "d1": "the cache stores recent pages for fast access",
    "d2": "a pointer stores the address of another value",
    "d3": "cache memory is faster than main memory access",
}

def tokens(text): return re.findall(r"[a-z]+", text.lower())

tf = {d: Counter(tokens(t)) for d, t in docs.items()}
df = Counter(w for counts in tf.values() for w in counts)
N = len(docs)

def tfidf(doc):
    counts = tf[doc]
    total = sum(counts.values())
    return {w: (c / total) * math.log(N / df[w] + 1) for w, c in counts.items()}

vectors = {d: tfidf(d) for d in docs}

print("top terms per document:")
for d, vec in vectors.items():
    top = sorted(vec.items(), key=lambda kv: -kv[1])[:3]
    print(f"  {d}: " + ", ".join(f"{w} {s:.3f}" for w, s in top))

def cosine(a, b):
    shared = set(a) & set(b)
    num = sum(a[w] * b[w] for w in shared)
    na = math.sqrt(sum(v * v for v in a.values()))
    nb = math.sqrt(sum(v * v for v in b.values()))
    return num / (na * nb) if na and nb else 0.0

print("\nsimilarity:")
for a, b in [("d1","d2"), ("d1","d3"), ("d2","d3")]:
    print(f"  {a} vs {b}: {cosine(vectors[a], vectors[b]):.4f}")
